func (this *Coinmate) fetchMarketsBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	params := GetArg(optionalArgs, 0, map[string]any{})
	_ = params

	response := (<-this.PublicGetTradingPairs(params))
	PanicOnError(response)
	//
	//     {
	//         "error":false,
	//         "errorMessage":null,
	//         "data": [
	//             {
	//                 "name":"BTC_EUR",
	//                 "firstCurrency":"BTC",
	//                 "secondCurrency":"EUR",
	//                 "priceDecimals":2,
	//                 "lotDecimals":8,
	//                 "minAmount":0.0002,
	//                 "tradesWebSocketChannelId":"trades-BTC_EUR",
	//                 "orderBookWebSocketChannelId":"order_book-BTC_EUR",
	//                 "tradeStatisticsWebSocketChannelId":"statistics-BTC_EUR"
	//             },
	//         ]
	//     }
	//
	var data any = this.SafeList(response, "data", []any{})
	var result any = []any{}
	for i := 0; IsLessThan(i, GetArrayLength(data)); i++ {
		var market any = GetValue(data, i)
		var id any = this.SafeString(market, "name")
		var baseId any = this.SafeString(market, "firstCurrency")
		var quoteId any = this.SafeString(market, "secondCurrency")
		var base any = this.SafeCurrencyCode(baseId)
		var quote any = this.SafeCurrencyCode(quoteId)
		var symbol any = Add(Add(base, "/"), quote)
		AppendToArray(&result, map[string]any{
			"id":             id,
			"symbol":         symbol,
			"base":           base,
			"quote":          quote,
			"settle":         nil,
			"baseId":         baseId,
			"quoteId":        quoteId,
			"settleId":       nil,
			"type":           "spot",
			"spot":           true,
			"margin":         false,
			"swap":           false,
			"future":         false,
			"option":         false,
			"active":         nil,
			"contract":       false,
			"linear":         nil,
			"inverse":        nil,
			"contractSize":   nil,
			"expiry":         nil,
			"expiryDatetime": nil,
			"strike":         nil,
			"optionType":     nil,
			"precision": map[string]any{
				"amount": this.ParseNumber(this.ParsePrecision(this.SafeString(market, "lotDecimals"))),
				"price":  this.ParseNumber(this.ParsePrecision(this.SafeString(market, "priceDecimals"))),
			},
			"limits": map[string]any{
				"leverage": map[string]any{
					"min": nil,
					"max": nil,
				},
				"amount": map[string]any{
					"min": this.SafeNumber(market, "minAmount"),
					"max": nil,
				},
				"price": map[string]any{
					"min": nil,
					"max": nil,
				},
				"cost": map[string]any{
					"min": nil,
					"max": nil,
				},
			},
			"created": nil,
			"info":    market,
		})
	}

	ch <- result
	return nil
}
func (this *Coinmate) ParseBalance(response any) any {
	var balances any = this.SafeDict(response, "data", map[string]any{})
	var result map[string]any = map[string]any{
		"info": response,
	}
	var currencyIds []string = ObjectKeys(balances)
	for i := 0; IsLessThan(i, GetArrayLength(currencyIds)); i++ {
		var currencyId any = GetValue(currencyIds, i)
		var code any = this.SafeCurrencyCode(currencyId)
		var balance any = this.SafeValue(balances, currencyId)
		var account any = this.Account()
		AddElementToObject(account, "free", this.SafeString(balance, "available"))
		AddElementToObject(account, "used", this.SafeString(balance, "reserved"))
		AddElementToObject(account, "total", this.SafeString(balance, "balance"))
		AddElementToObject(result, code, account)
	}
	return this.SafeBalance(result)
}

