func (this *Coinmate) ParseOrder(order any, optionalArgs ...any) any {
	//
	// limit sell
	//
	//     {
	//         "id": 781246605,
	//         "timestamp": 1584480015133,
	//         "trailingUpdatedTimestamp": null,
	//         "type": "SELL",
	//         "currencyPair": "ETH_BTC",
	//         "price": 0.0345,
	//         "amount": 0.01,
	//         "stopPrice": null,
	//         "originalStopPrice": null,
	//         "marketPriceAtLastUpdate": null,
	//         "marketPriceAtOrderCreation": null,
	//         "orderTradeType": "LIMIT",
	//         "hidden": false,
	//         "trailing": false,
	//         "clientOrderId": null
	//     }
	//
	// limit buy
	//
	//     {
	//         "id": 67527001,
	//         "timestamp": 1517931722613,
	//         "trailingUpdatedTimestamp": null,
	//         "type": "BUY",
	//         "price": 5897.24,
	//         "remainingAmount": 0.002367,
	//         "originalAmount": 0.1,
	//         "stopPrice": null,
	//         "originalStopPrice": null,
	//         "marketPriceAtLastUpdate": null,
	//         "marketPriceAtOrderCreation": null,
	//         "status": "CANCELLED",
	//         "orderTradeType": "LIMIT",
	//         "hidden": false,
	//         "avgPrice": null,
	//         "trailing": false,
	//     }
	//
	// cancelOrder
	//
	//    {
	//        "success": true,
	//        "remainingAmount": 0.1
	//    }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var id any = this.SafeString(order, "id")
	var timestamp any = this.SafeInteger(order, "timestamp")
	var side any = this.SafeStringLower(order, "type")
	var priceString any = this.SafeString(order, "price")
	var amountString any = this.SafeString(order, "originalAmount")
	var remainingString any = this.SafeString2(order, "remainingAmount", "amount")
	var status any = this.ParseOrderStatus(this.SafeString(order, "status"))
	var typeVar any = this.ParseOrderType(this.SafeString(order, "orderTradeType"))
	var averageString any = this.SafeString(order, "avgPrice")
	var marketId any = this.SafeString(order, "currencyPair")
	var symbol any = this.SafeSymbol(marketId, market, "_")
	var clientOrderId any = this.SafeString(order, "clientOrderId")
	return this.SafeOrder(map[string]any{
		"id":                 id,
		"clientOrderId":      clientOrderId,
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"lastTradeTimestamp": nil,
		"symbol":             symbol,
		"type":               typeVar,
		"timeInForce":        nil,
		"postOnly":           nil,
		"side":               side,
		"price":              priceString,
		"triggerPrice":       this.SafeNumber(order, "stopPrice"),
		"amount":             amountString,
		"cost":               nil,
		"average":            averageString,
		"filled":             nil,
		"remaining":          remainingString,
		"status":             status,
		"trades":             nil,
		"info":               order,
		"fee":                nil,
	}, market)
}

/**
 * @method
 * @name coinmate#createOrder
 * @description create a trade order
 * @see https://coinmate.docs.apiary.io/#reference/order/buy-limit-order/post
 * @see https://coinmate.docs.apiary.io/#reference/order/sell-limit-order/post
 * @see https://coinmate.docs.apiary.io/#reference/order/buy-instant-order/post
 * @see https://coinmate.docs.apiary.io/#reference/order/sell-instant-order/post
 * @param {string} symbol unified symbol of the market to create an order in
 * @param {string} type 'market' or 'limit'
 * @param {string} side 'buy' or 'sell'
 * @param {float} amount how much of currency you want to trade in units of base currency
 * @param {float} [price] the price at which the order is to be fulfilled, in units of the quote currency, ignored in market orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Coinmate) CreateOrderAsync(symbol any, typeVar any, side any, amount any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.createOrderBody(ch, symbol, typeVar, side, amount, optionalArgs...)
	return ch
}
func (this *Coinmate) createOrderBody(ch chan any, symbol any, typeVar any, side any, amount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	price := GetArg(optionalArgs, 0, nil)
	_ = price
	params := GetArg(optionalArgs, 1, map[string]any{})
	_ = params
	if IsTrue(IsEqual(this.Markets, nil)) {

		retRes118412 := (<-this.LoadMarketsAsync())
		PanicOnError(retRes118412)
	}
	var method any = Add("privatePost", this.Capitalize(side))
	var market any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"currencyPair": GetValue(market, "id"),
	}
	if IsTrue(IsEqual(typeVar, "market")) {
		if IsTrue(IsEqual(side, "buy")) {
			AddElementToObject(request, "total", this.AmountToPrecision(symbol, amount)) // amount in fiat
		} else {
			AddElementToObject(request, "amount", this.AmountToPrecision(symbol, amount)) // amount in fiat
		}
		method = Add(method, "Instant")
	} else {
		AddElementToObject(request, "amount", this.AmountToPrecision(symbol, amount)) // amount in crypto
		AddElementToObject(request, "price", this.PriceToPrecision(symbol, price))
		method = Add(method, this.Capitalize(typeVar))
	}
	var requestParams map[string]any = this.Extend(request, params)
	var response any = nil
	if IsTrue(IsEqual(method, "privatePostBuyInstant")) {

		response = (<-this.PrivatePostBuyInstant(requestParams))
		PanicOnError(response)
	} else if IsTrue(IsEqual(method, "privatePostSellInstant")) {

		response = (<-this.PrivatePostSellInstant(requestParams))
		PanicOnError(response)
	} else if IsTrue(IsEqual(method, "privatePostBuyLimit")) {

		response = (<-this.PrivatePostBuyLimit(requestParams))
		PanicOnError(response)
	} else if IsTrue(IsEqual(method, "privatePostSellLimit")) {

		response = (<-this.PrivatePostSellLimit(requestParams))
		PanicOnError(response)
	} else {
		panic(InvalidOrder(Add(Add(this.Id, " createOrder() does not support order type "), typeVar)))
	}
	var id any = this.SafeString(response, "data")

	ch <- this.SafeOrder(map[string]any{
		"info": response,
		"id":   id,
	}, market)
	return nil
}

